# .claude/scripts/primer-reconcile.py
# Commit-time governance drift checker -- generated by /primer reconcile.
# Author: Pierre Grothe
# Date: 2026-07-02
"""Validate .primer/policies/registry.yaml against live enforcement config.

Blocking (exit 2):

* a registry check whose id does not resolve per its kind's rule (STALE);
* a justifying ADR with no file, unless listed in ``known_gaps``;
* an enforced gate with no row in governance.md's gate tables. governance.md
  calls itself the enforcement inventory, but nothing checked the membership:
  the registry validated only that a check resolved to LIVE CONFIG, never that
  a reader could find it. Four gates were absent when this check was written;
* disagreement between the places that COUNT constitutional rules --
  constitutional-compliance.md's section header, its table's row count, and
  the total named in .claude/CLAUDE.md. Three files state the same number and
  none derives it from another, so the failure mode is editing two of them.
  Deliberately a count check and not a per-rule mapping: there is no slug
  column in that table and the mapping is genuinely not one-to-one, so a set
  comparison would report a modelling choice as drift.

Warning (exit 0):

* ORPHANED-CHECK -- a live pre-commit hook id or ratchet key that no registry
  policy claims;
* STAGE-DRIFT -- a cc-hook check found live under a hook event other than its
  declared stage (still resolves; the check is live, just not where declared);
* ADR-CATALOG -- an ADR file with no row in governance.md's catalog, or a
  marker count that disagrees with the table's actual row count;
* DECLARED-GAP -- a concern a policy states it does NOT mechanically enforce.
  ``status`` cannot carry this: it is derived from whether the DECLARED checks
  resolve, so a policy gating three of its five concerns reads ``enforced``
  and the rest are invisible. Warn-only permanently -- a declared gap is an
  honest statement, and blocking on it would create pressure to delete the
  declaration rather than the gap.

Every check fails OPEN when the file it reads is absent, so a project that
does not keep a given artefact is not blocked by a check about it.

Stdlib only. User-owned YAML is line-scanned, never YAML-parsed. The
registry is parsed with a line-oriented state machine over primer's
constrained emission format (see the skill's registry-schema.md).
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

__all__ = ["main"]

REGISTRY = Path(".primer/policies/registry.yaml")
PRECOMMIT = Path(".pre-commit-config.yaml")
SETTINGS = Path(".claude/settings.json")
WORKFLOWS = Path(".github/workflows")
ADR_DIR = Path(".primer/adr")
GOVERNANCE = Path(".primer/governance.md")

#: The govtable whose rows must cover every ADR file on disk. Its rows are
#: `| NNN | Title | policies |`; the marker carries a declared row count.
_ADR_CATALOG = re.compile(
    r"<!-- govtable:adr-catalog:start \(count=(\d+)\) -->(.*?)"
    r"<!-- govtable:adr-catalog:end -->",
    re.DOTALL,
)
_ADR_ROW = re.compile(r"^\|\s*(\d{3})\s*\|", re.MULTILINE)
_ADR_FILE = re.compile(r"^ADR-(\d{3})(?:-.*)?\.md$")

#: The govtables that together form the reader-facing enforcement inventory.
#: A registry check of a gate kind owes a row in one of them; which one is
#: not asserted, because a check legitimately moves between blocking, soft
#: and ratchet as it is tightened, and pinning the table would turn every
#: such promotion into a spurious failure.
_GOV_GATE_TABLE = re.compile(
    r"<!-- govtable:(gates-[a-z]+|cc-hooks):start \(count=\d+\) -->(.*?)"
    r"<!-- govtable:\1:end -->",
    re.DOTALL,
)

#: Rows qualify the first cell with the bundling hook or contract file that
#: actually runs the check -- ``catalog-read-outside-lock (`semgrep-blocking`)``,
#: ``.importlinter (import-contract)``. The check id is the cell without it.
_ROW_QUALIFIER = re.compile(r"\s*\(.*\)\s*$")

#: Check kinds that ARE gates and therefore owe a governance row. Excluded:
#: `generated-artifact`, which declares a build product and its generator
#: (`capability-map` -> .primer/capabilities.md), not a check. Its enforcement
#: is a separate pre-commit-hook check (`capability-map-freshness`) that owes
#: a row in its own right, so exempting the artifact loses no coverage.
_GATE_KINDS = frozenset(
    {"pre-commit-hook", "ratchet", "cc-hook", "import-contract"})

# cc-hook checks declare a `stage` drawn from this vocabulary (distinct
# from other kinds' per-edit|commit|push|ci|scheduled stage enum): the
# set of hook events a claimed cc-hook is expected to live under.
#
# Keep this table and registry-schema.md's cc-hook stage list IN SYNC. A
# stage outside this vocabulary used to fall through to a flat search with
# no complaint, which made STAGE-DRIFT unreachable for that row while
# governance.md printed the stage as though it had been validated -- two
# live rows (`post-tool`, `pre-tool`) sat in exactly that state until
# 2026-09-04. Unknown stages are now reported instead of ignored.
CC_HOOK_STAGE_EVENTS: dict[str, set[str]] = {
    "per-edit": {"PreToolUse", "PostToolUse"},
    "pre-tool": {"PreToolUse"},
    "post-tool": {"PostToolUse", "PostToolUseFailure"},
    "session-stop": {"Stop", "SubagentStop"},
    "per-prompt": {"UserPromptSubmit"},
    "session-start": {"SessionStart", "PreCompact"},
}

#: A cc-hook id is "the identifying substring of the settings command" --
#: usually a script path, but the schema also allows a dispatcher form
#: (`_run.py post-edit-lint`) where the target file need not appear at all.
#: Existence is therefore checked only for path-shaped ids; checking every
#: id would report the documented dispatcher convention as MISSING.
_SCRIPT_SUFFIXES = (".py", ".sh", ".js", ".ts", ".ps1", ".rb", ".pl")

_FLOW = re.compile(r"\[(.*?)\]")


def _flow_list(line: str) -> list[str]:
    """Parse a list value from a registry line.

    Handles both the emitted flow-list form (`key: [A, B]`) and a
    hand-authored bare scalar/CSV (`key: A` or `key: A, B`), so a
    non-bracketed value is never silently read as an empty list.

    Args:
        line: The raw registry line containing the list value.

    Returns:
        The stripped list items; empty only when the value is truly empty.
    """
    # Strip a trailing `#` comment first (as every other field parser here
    # does), so a bracket pair inside a comment -- e.g.
    # `justifying_adrs: ADR-9  # see [ADR-3]` -- cannot hijack the value.
    line = line.split("#")[0]
    m = _FLOW.search(line)
    if m:
        inner = m.group(1).strip()
        return [t.strip().strip("'\"") for t in inner.split(",")] if inner else []
    _, _, val = line.partition(":")
    val = val.strip()
    return [t.strip().strip("'\"") for t in val.split(",") if t.strip()] if val else []


def _scalar(raw_value: str) -> str:
    """Return a registry scalar value: comment/whitespace/quote stripped.

    Args:
        raw_value: The text after a ``key:`` (may carry a trailing comment
            and/or wrapping quotes, as a YAML formatter may emit).

    Returns:
        The value with a trailing ``#`` comment, surrounding whitespace, and
        one wrapping single/double-quote pair removed -- so a quoted
        ``kind: "pre-commit-hook"`` resolves the same as the bare form.
    """
    value = raw_value.split("#")[0].strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "'\"":
        value = value[1:-1]
    return value


def _ci_job_present(wf: Path, job: str) -> bool:
    """Return True when job is a key under the workflow's top-level jobs map.

    Args:
        wf: Path to the GitHub Actions workflow file.
        job: The job key to look for.

    Returns:
        True when `<job>:` appears as a child key of the top-level `jobs:`
        mapping -- not merely anywhere in the file (e.g. a same-named key
        under the `on:` trigger block does not count).
    """
    lines = wf.read_text(encoding="utf-8-sig", errors="replace").splitlines()
    n = len(lines)
    idx = 0
    while idx < n:
        # Find each top-level block-style `jobs:` header (flow-style
        # `jobs: {..}` is non-idiomatic and not parsed). A file may carry
        # more than one such block (duplicate top-level keys are invalid
        # YAML but do occur); scan every block and match in any of them so
        # a real job is never wrongly reported STALE.
        if not re.match(r"^jobs:[ \t]*($|#)", lines[idx]):
            idx += 1
            continue
        idx += 1  # advance past the `jobs:` header
        job_indent = None
        while idx < n:
            line = lines[idx]
            stripped = line.strip()
            if stripped == "" or stripped.startswith("#"):
                idx += 1
                continue
            indent = len(line) - len(line.lstrip(" \t"))
            if indent == 0:
                break  # dedented; re-examine this line as a possible header
            # Job keys are the shallowest-indent direct children of jobs:.
            if job_indent is None or indent < job_indent:
                job_indent = indent
            # Allow a single- or double-quoted job key (`"build":`), a valid
            # YAML style a formatter may emit or a numeric-like name requires.
            if indent == job_indent and re.match(
                    rf"^(['\"]?){re.escape(job)}\1:(?:\s|$)", stripped):
                return True
            idx += 1
    return False


def _token_present(token: str, text: str) -> bool:
    """Return True when token appears as a discrete token, not a substring.

    Args:
        token: The identifier to look for.
        text: The text to search.

    Returns:
        True when token starts at a boundary (not preceded by a word or
        hyphen character, so `test` does not match `pytest`/`latest`/
        `attestation`) and is not immediately followed by a word character.
        A following hyphen or dot IS allowed, so a versioned/suffixed live
        name resolves (id `ruff-check` matches `ruff-check-v2.py` and
        `ruff-check.py`) while `ruff-checker` still does not.
    """
    if not token:
        return False
    return re.search(rf"(?<![\w-]){re.escape(token)}(?![\w])", text) is not None


def parse_registry(text: str) -> tuple[list[dict], set[str], str]:
    """Parse the constrained registry format.

    Args:
        text: Full registry.yaml content.

    Returns:
        A (policies, known_gaps, baselines_path) tuple; each policy dict
        carries slug, status, justifying_adrs, and checks (field dicts).
    """
    policies: list[dict] = []
    gaps: set[str] = set()
    baselines = ".ratchet/baselines.json"
    pol: dict | None = None
    chk: dict | None = None
    in_checks = False
    in_gaps = False
    for raw in text.splitlines():
        line = raw.rstrip()
        if line.startswith("known_gaps:"):
            gaps = {g.replace("ADR-", "") for g in _flow_list(line)}
        elif line.startswith("baselines:"):
            baselines = _scalar(line.split(":", 1)[1])
        elif re.match(r"^  - slug:", line):
            slug = _scalar(line.split(":", 1)[1])
            pol = {"slug": slug, "adrs": [], "checks": [], "status": "",
                   "constitutional": False, "gaps": []}
            policies.append(pol)
            in_checks = in_gaps = False
        elif pol is not None and re.match(r"^    justifying_adrs:", line):
            pol["adrs"] = _flow_list(line)
        elif pol is not None and re.match(r"^    constitutional:", line):
            pol["constitutional"] = _scalar(line.split(":", 1)[1]) == "true"
        elif pol is not None and re.match(r"^    gaps:", line):
            in_gaps, in_checks = True, False
        elif in_gaps and re.match(r"^      - ", line):
            pol["gaps"].append(_scalar(line.split("- ", 1)[1]))
        elif pol is not None and re.match(r"^    checks:", line):
            in_checks = True
            in_gaps = False
        elif pol is not None and re.match(r"^    status:", line):
            pol["status"] = _scalar(line.split(":", 1)[1])
            in_checks = in_gaps = False
        elif in_checks and re.match(r"^      - kind:", line):
            chk = {"kind": _scalar(line.split(":", 1)[1])}
            pol["checks"].append(chk)
        elif in_checks and chk is not None and re.match(r"^        \w", line):
            key, _, val = line.strip().partition(":")
            chk[key] = _scalar(val)
    return policies, gaps, baselines


def live_precommit_ids() -> set[str]:
    """Collect every hook id declared in .pre-commit-config.yaml.

    Returns:
        The set of `- id:` values; empty when the file is absent.
    """
    if not PRECOMMIT.is_file():
        return set()
    text = PRECOMMIT.read_text(encoding="utf-8-sig", errors="replace")
    return {mid.strip("'\"")
            for mid in re.findall(r"^\s*-\s*id:\s*(\S+)", text, re.M)}


def _collect_keys(obj: object) -> set[str]:
    """Collect dict keys recursively at every nesting depth.

    Args:
        obj: Any JSON-decoded value.

    Returns:
        Every dict key found in obj, at any depth, as strings.
    """
    keys: set[str] = set()
    if isinstance(obj, dict):
        for key, value in obj.items():
            keys.add(str(key))
            keys.update(_collect_keys(value))
    elif isinstance(obj, list):
        for item in obj:
            keys.update(_collect_keys(item))
    return keys


_ratchet_key_cache: dict[str, set[str]] = {}


def live_ratchet_keys(baseline_path: str) -> set[str]:
    """Collect ratchet baseline keys at any nesting depth, cached per path.

    Args:
        baseline_path: Project-root-relative path to the baseline JSON file.

    Returns:
        Every dict key found in the decoded JSON, at any depth; empty when
        the file is missing or fails to decode. Each distinct absolute
        path is loaded from disk at most once per process.
    """
    path = Path(baseline_path)
    cache_key = str(path.resolve())
    if cache_key in _ratchet_key_cache:
        return _ratchet_key_cache[cache_key]
    keys: set[str] = set()
    if path.is_file():
        try:
            data = json.loads(path.read_text(encoding="utf-8-sig"))
        except (json.JSONDecodeError, UnicodeDecodeError, OSError):
            data = None
        if data is not None:
            keys = _collect_keys(data)
    _ratchet_key_cache[cache_key] = keys
    return keys


def _collect_numeric_keys(obj) -> set[str]:
    """Collect dict keys whose value is a number, at any depth.

    Args:
        obj: Decoded JSON value (dict, list, or scalar).

    Returns:
        Keys mapping directly to an int or float (bool excluded).
        Ratchet baselines map check ids to numeric thresholds; container
        and metadata keys (a 'counts' wrapper dict, an 'updated'
        timestamp string) are structure, not checks.
    """
    keys: set[str] = set()
    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                keys.add(str(key))
            else:
                keys.update(_collect_numeric_keys(value))
    elif isinstance(obj, list):
        for item in obj:
            keys.update(_collect_numeric_keys(item))
    return keys


def numeric_ratchet_keys(baseline_path: str) -> set[str]:
    """Collect only numeric-valued baseline keys (the orphan-scan universe).

    Args:
        baseline_path: Project-root-relative path to the baseline JSON file.

    Returns:
        Keys whose value is a number, at any depth; empty when the file
        is missing or fails to decode. resolve() keeps using
        live_ratchet_keys (any-depth presence) so container-claiming
        registries still resolve unchanged.
    """
    path = Path(baseline_path)
    if not path.is_file():
        return set()
    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except (json.JSONDecodeError, UnicodeDecodeError, OSError):
        return set()
    return _collect_numeric_keys(data)


def settings_commands_by_event() -> dict[str, str]:
    """Concatenate hook command strings in .claude/settings.json, per event.

    Returns:
        A mapping of hook event name (e.g. "PreToolUse") to its
        concatenated command/prompt strings (including agent-type hook
        prompts, which carry a `prompt` field instead of, or alongside,
        `command`); empty when settings.json is absent or malformed.
    """
    if not SETTINGS.is_file():
        return {}
    try:
        data = json.loads(SETTINGS.read_text(encoding="utf-8-sig"))
    except (json.JSONDecodeError, UnicodeDecodeError, OSError):
        return {}
    # Tolerate any malformed shape (hooks null, a list, non-dict entries):
    # degrade to no commands rather than crash the whole governance check.
    hooks = data.get("hooks") if isinstance(data, dict) else None
    if not isinstance(hooks, dict):
        return {}
    out: dict[str, list[str]] = {}
    for event, entries in hooks.items():
        if not isinstance(entries, list):
            continue
        bucket = out.setdefault(str(event), [])
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            inner = entry.get("hooks")
            if not isinstance(inner, list):
                continue  # explicit null / non-list -> no commands, no crash
            for hook in inner:
                if not isinstance(hook, dict):
                    continue
                if "command" in hook:
                    bucket.append(hook.get("command", ""))
                if "prompt" in hook:
                    bucket.append(str(hook.get("prompt", "")))
    return {event: "\n".join(cmds) for event, cmds in out.items()}


def resolve(chk: dict, pc_ids: set[str], ratchets: set[str],
            commands_by_event: dict[str, str]) -> bool:
    """Apply the per-kind resolution rule for one registry check.

    Args:
        chk: Parsed check fields (kind, id, optional bundled_into,
            optional baseline_path, optional stage).
        pc_ids: Live pre-commit hook ids.
        ratchets: Live ratchet baseline keys from the default source
            (registry `baselines:` override or .ratchet/baselines.json).
        commands_by_event: Concatenated cc-hook command/prompt strings,
            keyed by hook event name.

    Returns:
        True when the check resolves to live config.
    """
    kind, cid = chk.get("kind", ""), chk.get("id", "")
    if not cid:
        return False
    if kind == "pre-commit-hook":
        return cid in pc_ids or chk.get("bundled_into", "") in pc_ids
    if kind == "cc-hook":
        # Wiring alone is not liveness. A hook is commonly wired as
        # `G="...x.py"; [ -f "$G" ] || exit 0; python "$G"`, so the id stays
        # present in settings.json after the script is renamed or deleted
        # and the shell guard then exits 0 silently. Resolving on the
        # command string alone reported such a policy `enforced` while it
        # gated nothing -- the one hook breakage this checker could not see.
        # Only path-shaped ids are checked; see _SCRIPT_SUFFIXES.
        if cid.endswith(_SCRIPT_SUFFIXES) and not Path(cid).is_file():
            print(f"MISSING-SCRIPT (warn): cc-hook '{cid}' is wired in "
                  f"settings.json but the script does not exist; the shell "
                  f"guard around it exits 0, so the hook silently does "
                  f"nothing")
            return False
        declared_stage = chk.get("stage", "")
        stage_events = CC_HOOK_STAGE_EVENTS.get(declared_stage)
        if stage_events is None:
            if declared_stage:
                print(f"UNKNOWN-STAGE (warn): cc-hook '{cid}' declares stage "
                      f"'{declared_stage}', which is not one of "
                      f"{sorted(CC_HOOK_STAGE_EVENTS)}; its stage cannot be "
                      f"verified and STAGE-DRIFT will not fire for it")
            # No declared stage, or a value outside the known vocabulary:
            # fall back to a flat search across every event (unchanged
            # prior behavior -- resolution never depended on stage before).
            return _token_present(
                cid, "\n".join(commands_by_event.values()))
        declared_text = "\n".join(
            commands_by_event.get(evt, "") for evt in stage_events)
        if _token_present(cid, declared_text):
            return True
        for evt, text in commands_by_event.items():
            if evt in stage_events:
                continue
            if _token_present(cid, text):
                print(f"STAGE-DRIFT (warn): cc-hook '{cid}' declared stage "
                      f"'{chk.get('stage')}' (events "
                      f"{sorted(stage_events)}) but found live under "
                      f"event '{evt}' instead")
                return True
        return False  # absent everywhere -> MISSING
    if kind == "ci-job":
        fname, _, job = cid.partition(":")
        wf = WORKFLOWS / fname
        if not (job and wf.is_file()):
            return False
        return _ci_job_present(wf, job)
    if kind == "ratchet":
        override = chk.get("baseline_path")
        keys = live_ratchet_keys(override) if override else ratchets
        return cid in keys
    if kind == "import-contract":
        if Path(cid).is_file():
            return True
        cfg = Path(".importlinter")
        return cfg.is_file() and _token_present(
            cid, cfg.read_text(encoding="utf-8-sig", errors="replace"))
    if kind == "agent-rule":
        return Path(cid).is_file()
    if kind == "generated-artifact":
        # A build/regeneration declaration, not a live-enforcement check --
        # registry-schema.md documents it as intentionally outside the
        # per-kind resolution rules, so it never resolves to STALE.
        return True
    return False


def _listed_gate_rows() -> set[str]:
    """Return the check ids that governance.md's gate tables actually list.

    Returns:
        Normalised first-cell values across every gate table, with the
        bundling qualifier and backticks stripped. Empty when governance.md
        is absent.
    """
    if not GOVERNANCE.is_file():
        return set()
    text = GOVERNANCE.read_text(encoding="utf-8-sig", errors="replace")
    listed: set[str] = set()
    for match in _GOV_GATE_TABLE.finditer(text):
        rows = [
            line for line in match.group(2).splitlines()
            if line.startswith("|")
        ]
        # rows[0] is the column header, rows[1] the |---| separator.
        for line in rows[2:]:
            cell = line.split("|")[1].strip()
            listed.add(_ROW_QUALIFIER.sub("", cell).strip().strip("`"))
    listed.discard("")
    return listed


def gate_table_problems(policies: list[dict]) -> list[str]:
    """Find enforced gates that governance.md does not list.

    governance.md calls itself the enforcement inventory and its own header
    asserts "every hook traces to a justifying ADR", but nothing checked the
    membership: the registry validated only that a check resolves to LIVE
    CONFIG, never that a reader could find it. Four enforced gates were absent
    when this check was written -- `catalog-save-outside-lock`,
    `canonical-seams`, `float64-money-columns` and `blocking-frame-io` -- one
    of them for long enough that a second rule was added to the same policy
    without anyone noticing the first had never appeared.

    Blocking rather than warn-only, deliberately. pre-commit prints a passing
    hook's stdout to nobody, so the sibling warn-only catalog check is invisible
    at the moment it fires and only ever reaches someone running this script by
    hand -- which is precisely how the four gates stayed missing. The population
    is zero at introduction, so this ships as a bright line rather than a
    burndown.

    Args:
        policies: Parsed registry policies, as returned by ``parse_registry``.

    Returns:
        Human-readable blocking lines; empty when every gate is listed.
    """
    if not GOVERNANCE.is_file():
        return []
    listed = _listed_gate_rows()
    if not listed:
        return []  # no gate tables at all -> not this check's drift to report
    problems: list[str] = []
    seen: set[str] = set()
    for pol in policies:
        if pol["status"] == "retired":
            continue
        for chk in pol["checks"]:
            kind, cid = chk.get("kind", ""), chk.get("id", "")
            if kind not in _GATE_KINDS or not cid or cid in listed:
                continue
            if cid in seen:
                continue  # one id may be claimed by several policies
            seen.add(cid)
            problems.append(
                f"{pol['slug']}: {kind} '{cid}' is enforced but has no row in "
                "governance.md's gate tables -- add the row and bump the "
                "marker count")
    return problems


def adr_catalog_warnings() -> list[str]:
    """Find ADR files missing from governance.md's adr-catalog table.

    The catalog is the reader-facing index of every architecture decision.
    Nothing else notices when an ADR lands without a row: the registry only
    validates the reverse direction (a policy citing an ADR that has no
    file), so five ADRs accumulated unlisted before this check existed.

    Also reports a declared marker count that disagrees with the actual row
    count -- the marker is what a regenerator trusts, so a stale count is
    how a hand-inserted row gets silently dropped later.

    Returns:
        Human-readable warning lines; empty when the catalog is complete.
    """
    if not GOVERNANCE.is_file() or not ADR_DIR.is_dir():
        return []
    match = _ADR_CATALOG.search(
        GOVERNANCE.read_text(encoding="utf-8-sig", errors="replace"))
    if match is None:
        return []
    declared = int(match.group(1))
    body = match.group(2)
    listed = set(_ADR_ROW.findall(body))
    on_disk = {
        m.group(1)
        for m in (_ADR_FILE.match(p.name) for p in ADR_DIR.glob("ADR-*.md"))
        if m is not None
    }
    warnings: list[str] = []
    for num in sorted(on_disk - listed):
        warnings.append(
            f"ADR-CATALOG (warn): ADR-{num} has a file but no row in "
            "governance.md's adr-catalog table -- add the row and bump the "
            "marker count")
    if declared != len(listed):
        warnings.append(
            f"ADR-CATALOG (warn): adr-catalog marker says count={declared} "
            f"but the table has {len(listed)} rows")
    return warnings


def constitutional_count_problems() -> list[str]:
    """Find disagreement between the places that count constitutional rules.

    Three files state the same number and none of them derives it from another:
    ``.claude/rules/constitutional-compliance.md`` in its section header and
    again in its table's row count, and ``.claude/CLAUDE.md`` in the sentence
    that names the authoritative total. Promoting a rule means editing all
    three, and nothing checked that they agreed -- so the failure mode is
    editing two and shipping a constitution that miscounts itself.

    Deliberately a COUNT check and not a per-rule mapping. There is no slug
    column in that table, and the mapping is genuinely not one-to-one: rule 6
    ("no ADR references in source") is enforced inside the ``code-quality``
    policy, which is not constitutional, so a strict set comparison would
    report drift that is really a modelling choice. The count catches the
    mechanical error -- an edit that lands in one file -- without pretending to
    an equivalence that does not hold.

    Returns:
        Blocking lines; empty when the three agree or the files are absent.
    """
    rules = Path(".claude/rules/constitutional-compliance.md")
    claude_md = Path(".claude/CLAUDE.md")
    if not rules.is_file():
        return []
    text = rules.read_text(encoding="utf-8", errors="replace")
    header = re.search(r"^## Project-specific constitutional rules \((\d+)\)", text, re.M)
    if header is None:
        return []
    declared = int(header.group(1))
    rows = len(re.findall(r"^\| \d+ \| ", text, re.M))
    problems: list[str] = []
    if rows != declared:
        problems.append(
            f"constitutional-compliance.md: header says {declared} project rules "
            f"but the table has {rows} rows")
    if claude_md.is_file():
        stated = re.search(r"\((\d+) project rules", claude_md.read_text(
            encoding="utf-8", errors="replace"))
        if stated is not None and int(stated.group(1)) != declared:
            problems.append(
                f".claude/CLAUDE.md says {stated.group(1)} project rules but "
                f"constitutional-compliance.md declares {declared}")
    return problems


def policy_gap_notes(policies: list[dict]) -> list[str]:
    """Surface pillars a policy declares it does NOT mechanically enforce.

    ``status`` cannot carry this. The schema derives it from whether the
    DECLARED checks resolve, so a policy that gates two of its five pillars
    reads ``enforced`` and the other three are invisible to every tool -- which
    is how a policy comes to look stronger than it is. ``credential-hygiene``
    hit exactly that and recorded its gaps as a YAML comment no parser could
    read.

    Warn-only, permanently. A declared gap is an honest statement, not drift;
    blocking on it would create pressure to delete the declaration rather than
    the gap.

    Args:
        policies: Parsed registry policies.

    Returns:
        Warning lines, one per declared gap.
    """
    notes: list[str] = []
    for pol in policies:
        if pol["status"] == "retired":
            continue
        for gap in pol["gaps"]:
            notes.append(
                f"DECLARED-GAP (warn): {pol['slug']} -- {gap}")
    return notes


def main() -> int:
    """Run the drift check and print findings.

    Returns:
        0 when clean (orphans warn only), 2 on blocking drift.
    """
    if not REGISTRY.is_file():
        return 0  # no registry -> nothing to enforce yet
    _ratchet_key_cache.clear()  # fresh disk reads per run (in-process safe)
    policies, gaps, baselines = parse_registry(
        REGISTRY.read_text(encoding="utf-8-sig", errors="replace"))
    pc_ids = live_precommit_ids()
    ratchets = live_ratchet_keys(baselines)
    commands_by_event = settings_commands_by_event()
    blocking: list[str] = []
    claimed_pc: set[str] = set()
    claimed_ratchet: set[str] = set()
    for pol in policies:
        retired = pol["status"] == "retired"
        # A retired policy still legitimately claims its live checks, so
        # populate the claimed sets from it too -- only its blocking
        # validation is skipped (else its ids would be reported ORPHANED-CHECK).
        for chk in pol["checks"]:
            # Claim into the SAME namespace the orphan scan searches, keyed by
            # kind: a live pre-commit hook id is only "claimed" by a
            # pre-commit-hook check (directly or via bundled_into); a
            # default-baseline ratchet key only by a ratchet check reading that
            # same default baseline. A flat, kind-agnostic claimed set would let
            # an incidental cross-kind id-string collision (a ratchet key equal
            # to a live hook id) mask a genuine orphan.
            kind, cid = chk.get("kind", ""), chk.get("id", "")
            if kind == "pre-commit-hook":
                claimed_pc.add(cid)
                claimed_pc.add(chk.get("bundled_into", ""))
            elif kind == "ratchet" and chk.get("baseline_path", baselines) == baselines:
                claimed_ratchet.add(cid)
            if not retired and not resolve(
                    chk, pc_ids, ratchets, commands_by_event):
                blocking.append(
                    f"{pol['slug']}: {chk.get('kind')} '{chk.get('id')}' "
                    "does not resolve to live config (STALE)")
        if retired:
            continue
        for adr in pol["adrs"]:
            num = adr.replace("ADR-", "")
            if num in gaps:
                continue
            if not (any(ADR_DIR.glob(f"ADR-{num}.md"))
                    or any(ADR_DIR.glob(f"ADR-{num}-*.md"))):
                blocking.append(
                    f"{pol['slug']}: {adr} has no file in .primer/adr/")
    # The orphan scan uses ONLY the default baseline, NOT per-check
    # `baseline_path` override baselines: those are large project DATA
    # (coverage, file-size -- e.g. 131 nested per-module keys plus metadata),
    # not a per-key governance surface. The check that references an override
    # already claims its key; collecting the override's other keys would flood
    # warn-only ORPHANED-CHECK noise on every commit (seen on nexus-sn: 136
    # false orphans). Override baselines are still read for resolve().
    # It also considers ONLY numeric-valued keys: baselines map check ids
    # to numeric thresholds, so container/metadata keys (a 'counts'
    # wrapper, an 'updated' timestamp) are structure, not checks (seen on
    # mds: 2 permanent false warns on every commit).
    orphans = sorted(
        (pc_ids - claimed_pc)
        | (numeric_ratchet_keys(baselines) - claimed_ratchet))
    for orphan in orphans:
        print(f"ORPHANED-CHECK (warn): '{orphan}' is live but claimed by "
              "no registry policy -- register it via /primer reconcile")
    blocking.extend(gate_table_problems(policies))
    blocking.extend(constitutional_count_problems())
    for note in policy_gap_notes(policies):
        print(note)
    for warning in adr_catalog_warnings():
        print(warning)
    if blocking:
        print("PRIMER-RECONCILE: governance drift -- fix before commit "
              "(run /primer reconcile):", file=sys.stderr)
        for item in blocking:
            print(f"  {item}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
